import{_ as r,C as h,o as e,c as s,a3 as t,b as o,w as E,a as n,E as c,a6 as l}from"./chunks/framework.Ba39LDvt.js";const p=JSON.parse('{"title":"上科大 IC 生态","description":"从信息学院、研究中心和 EE 培养方案出发，认识上海科技大学的集成电路学习与科研路径。","frontmatter":{"title":"上科大 IC 生态","description":"从信息学院、研究中心和 EE 培养方案出发，认识上海科技大学的集成电路学习与科研路径。"},"headers":[],"relativePath":"shanghaitech/index.md","filePath":"shanghaitech/index.md","lastUpdated":1795525517000}'),d={name:"shanghaitech/index.md"};function B(A,a,g,f,u,C){const i=h("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="上科大-ic-生态" tabindex="-1">上科大 IC 生态 <a class="header-anchor" href="#上科大-ic-生态" aria-label="Permalink to &quot;上科大 IC 生态&quot;">​</a></h1><p>在上海科技大学，集成电路（Integrated Circuit，IC）不是孤立的一门专业课：它连接半导体材料与器件、电路设计、计算机体系结构、设计自动化，也与视觉、医疗电子和能源系统交叉。本板块帮助你把「学什么课、关注哪些老师、在哪里做实验、有哪些培养机会」放到同一张地图上。</p><h2 id="信息学院-从器件到系统" tabindex="-1">信息学院：从器件到系统 <a class="header-anchor" href="#信息学院-从器件到系统" aria-label="Permalink to &quot;信息学院：从器件到系统&quot;">​</a></h2><p>信息科学与技术学院（School of Information Science and Technology，SIST）设有计算机科学与技术（CS）和电子信息工程（EE）两个本科专业。学院本科招生介绍强调「宽口径、厚基础、重交叉」，并建设导论课、基础课、专业课到高阶课的本硕博一体化课程体系。</p><p><strong>学院官网首页统计口径：截至 2026 年 09 月</strong>，学院有 <strong>1165 名本科生、1727 名研究生、83 个课题组、144 位教授、7 个研究中心</strong>。这些是全学院数据，不能理解为 IC 方向人数或招生名额；不同年份的介绍材料也不宜混为同一统计时点。</p><p>学院七个研究中心为：视觉与数据智能中心、智能网络中心、后摩尔器件与集成系统中心、智慧电气科学中心、自动化与机器人中心、系统与安全中心、智能医学信息研究中心。对 IC 学生，以下三个是尤其直接的入口：</p><table tabindex="0"><thead><tr><th>研究中心</th><th>与 IC 学习、科研的连接</th></tr></thead><tbody><tr><td>后摩尔器件与集成系统中心（PMICC）</td><td>覆盖低温电子、自旋电子、光电子、微机电系统、宽禁带半导体，以及低功耗电路、可重构计算、智能 EDA 和定制化片上系统</td></tr><tr><td>智慧电气科学中心（CiPES）</td><td>连接电源管理、功率变换、无线电能传输、宽禁带器件应用与能源系统，适合从「芯片怎样给系统供能」切入</td></tr><tr><td>系统与安全中心（SSC）</td><td>关注计算系统效率与安全，涉及体系结构、存储、高性能计算及软硬件协同安全，与处理器和系统设计相接</td></tr></tbody></table><p>中心是组织入口，方向是问题入口，两者不是一一对应关系。例如，光计算跨越器件与 AI 硬件，硬件安全既涉及电路也涉及微架构。选方向时应进一步看老师近期论文和项目，而不是只看中心名称。</p><h2 id="学院—中心—方向—课题组" tabindex="-1">学院—中心—方向—课题组 <a class="header-anchor" href="#学院—中心—方向—课题组" aria-label="Permalink to &quot;学院—中心—方向—课题组&quot;">​</a></h2><p>下面只展示代表性连接，<strong>不是完整组织架构或排名</strong>；课题组与方向依据本站师资数据及学院公开介绍整理。</p>',10)),(e(),o(l,null,{default:E(()=>[c(i,{id:"mermaid-65",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E4%BF%A1%E6%81%AF%E7%A7%91%E5%AD%A6%E4%B8%8E%E6%8A%80%E6%9C%AF%E5%AD%A6%E9%99%A2%20SIST%22%5D%20--%3E%20P%5B%22%E5%90%8E%E6%91%A9%E5%B0%94%E5%99%A8%E4%BB%B6%E4%B8%8E%E9%9B%86%E6%88%90%E7%B3%BB%E7%BB%9F%E4%B8%AD%E5%BF%83%20PMICC%22%5D%0A%20%20S%20--%3E%20E%5B%22%E6%99%BA%E6%85%A7%E7%94%B5%E6%B0%94%E7%A7%91%E5%AD%A6%E4%B8%AD%E5%BF%83%20CiPES%22%5D%0A%20%20S%20--%3E%20C%5B%22%E7%B3%BB%E7%BB%9F%E4%B8%8E%E5%AE%89%E5%85%A8%E4%B8%AD%E5%BF%83%20SSC%22%5D%0A%20%20P%20--%3E%20D%5B%22%E5%8D%8A%E5%AF%BC%E4%BD%93%E5%99%A8%E4%BB%B6%E4%B8%8E%E6%96%B0%E5%9E%8B%E5%AD%98%E5%82%A8%22%5D%0A%20%20P%20--%3E%20O%5B%22%E5%85%89%E7%94%B5%E5%AD%90%E4%B8%8E%E9%9B%86%E6%88%90%E5%85%89%E5%AD%90%22%5D%0A%20%20P%20--%3E%20M%5B%22MEMS%20%E4%B8%8E%E4%BC%A0%E6%84%9F%22%5D%0A%20%20P%20--%3E%20V%5B%22%E6%95%B0%E5%AD%97%20VLSI%20%E4%B8%8E%E6%99%BA%E8%83%BD%E8%AE%A1%E7%AE%97%22%5D%0A%20%20P%20--%3E%20A%5B%22%E6%A8%A1%E6%8B%9F%E4%B8%8E%E5%8C%BB%E7%96%97%E7%94%B5%E5%AD%90%22%5D%0A%20%20P%20--%3E%20T%5B%22EDA%20%E4%B8%8E%E8%AE%BE%E8%AE%A1%E6%96%B9%E6%B3%95%E5%AD%A6%22%5D%0A%20%20E%20--%3E%20W%5B%22%E7%94%B5%E6%BA%90%E7%AE%A1%E7%90%86%E4%B8%8E%E5%8A%9F%E7%8E%87%E7%94%B5%E5%AD%90%22%5D%0A%20%20C%20--%3E%20H%5B%22%E4%BD%93%E7%B3%BB%E7%BB%93%E6%9E%84%E4%B8%8E%E7%B3%BB%E7%BB%9F%E5%AE%89%E5%85%A8%22%5D%0A%20%20D%20--%3E%20K%5B%22%E5%AF%87%E7%85%A6%E4%B8%B0%E8%AF%BE%E9%A2%98%E7%BB%84%22%5D%0A%20%20O%20--%3E%20B%5B%22%E9%99%88%E4%BD%B0%E4%B9%90%EF%BC%9A%E5%85%89%E7%94%B5%E5%99%A8%E4%BB%B6%E5%AE%9E%E9%AA%8C%E5%AE%A4%22%5D%0A%20%20M%20--%3E%20U%5B%22%E5%90%B4%E6%B6%9B%EF%BC%9ASMALL%22%5D%0A%20%20V%20--%3E%20L%5B%22%E5%A8%84%E9%91%AB%EF%BC%9AVSPLab%22%5D%0A%20%20A%20--%3E%20N%5B%22%E5%90%95%E5%AE%8F%E9%B8%A3%EF%BC%9ABICML%22%5D%0A%20%20T%20--%3E%20Z%5B%22%E5%91%A8%E5%B9%B3%E5%BC%BA%EF%BC%9A%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AF%E4%B8%8E%E7%B3%BB%E7%BB%9F%E5%AE%9E%E9%AA%8C%E5%AE%A4%22%5D%0A%20%20W%20--%3E%20R%5B%22%E7%8E%8B%E6%B5%A9%E5%AE%87%EF%BC%9APEARL%22%5D%0A%20%20H%20--%3E%20X%5B%22%E8%82%96%E5%8E%9F%E8%AF%BE%E9%A2%98%E7%BB%84%22%5D%0A%20%20classDef%20base%20fill%3A%23e6f4f6%2Cstroke%3A%23007f95%2Ccolor%3A%230b2832%0A%20%20classDef%20bridge%20fill%3A%23fff4e8%2Cstroke%3A%23b7791f%2Ccolor%3A%235c3a0a%0A%20%20classDef%20app%20fill%3A%23fbeaf0%2Cstroke%3A%23ba3f5c%2Ccolor%3A%235a1226%0A%20%20class%20S%2CP%2CE%2CC%20base%0A%20%20class%20D%2CO%2CM%2CV%2CA%2CT%2CW%2CH%20bridge%0A%20%20class%20K%2CB%2CU%2CL%2CN%2CZ%2CR%2CX%20app%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>完整方向与交叉关系见 <a href="/shanghaitech-ic-wiki-dev.github.io/research/">科研方向</a>，按方向查老师见 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/faculty">教授与课题组</a>。</p><h2 id="ee-本科-143-学分如何连接-ic" tabindex="-1">EE 本科：143 学分如何连接 IC <a class="header-anchor" href="#ee-本科-143-学分如何连接-ic" aria-label="Permalink to &quot;EE 本科：143 学分如何连接 IC&quot;">​</a></h2><p>以下依据 <strong>2026 级电子信息工程本科培养方案</strong>；其他年级应使用本年级版本。方案要求修满至少 <strong>143 学分</strong>，其中人文社科通识 53 学分、自然科学通识 30 学分、专业课程 51 学分、任选课程 9 学分。</p><p>专业课程由 <strong>32 学分必修 + 19 学分选修</strong>组成。必修部分包含计算机编程、电路基础及实验、电磁学及课程设计、信号与系统及实验、模拟电路、数字电路，以及毕业论文。这里的基础不只服务于 IC：信号、器件、电磁和编程能力，也为通信、控制、光电与电力电子保留后续选择。</p><h3 id="专业限选-三选二-不是任选其一" tabindex="-1">专业限选：三选二，不是任选其一 <a class="header-anchor" href="#专业限选-三选二-不是任选其一" aria-label="Permalink to &quot;专业限选：三选二，不是任选其一&quot;">​</a></h3><p>19 学分本学科选修中包含 <strong>8 学分专业限选</strong>，要求从以下三门各 4 学分课程中<strong>至少选两门</strong>：</p><ul><li><strong>EE120 半导体器件基础</strong>：进一步连接器件、工艺与晶体管工作机制。</li><li><strong>EE140 通信原理</strong>：连接信号处理与通信系统。</li><li><strong>EE160 控制原理</strong>：连接动态系统、反馈与控制。</li></ul><p>如果三门都修，多余学分计入本学科选修的 19 学分中。不要因为当前偏向数字 IC，就在未核对方案前跳过专业限选要求。</p><h3 id="面向-ic-的选课思路" tabindex="-1">面向 IC 的选课思路 <a class="header-anchor" href="#面向-ic-的选课思路" aria-label="Permalink to &quot;面向 IC 的选课思路&quot;">​</a></h3><ul><li><strong>数字电路与芯片实现</strong>：从 <a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee115b">EE115B 数字电路</a> 到 <a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee113">EE113 数字集成电路 I</a>，再接 <a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee291f">EE291F 数字 VLSI 设计流程</a>。</li><li><strong>模拟与混合信号</strong>：先打好电路基础、<a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee115a">EE115A 模拟电路</a> 和 <a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee150">信号与系统</a>，再进入模拟集成电路与相关实验。</li><li><strong>器件、光电与 MEMS</strong>：在物理、电磁学、半导体器件基础之上，按研究问题选择工艺、光电与平台实验课程。</li><li><strong>架构、AI 芯片与 EDA</strong>：结合 <a href="/shanghaitech-ic-wiki-dev.github.io/courses/cs110">CS110</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee219">EE219</a> 及算法、数学课程，不把写 RTL 与理解系统割裂。</li></ul><p>这些是学习建议，不是新增毕业要求。具体课程、先修与开课学期请看 <a href="/shanghaitech-ic-wiki-dev.github.io/courses/">课程地图</a>。</p><h2 id="本研一体-按先修能力-而不只按年级选课" tabindex="-1">本研一体：按先修能力，而不只按年级选课 <a class="header-anchor" href="#本研一体-按先修能力-而不只按年级选课" aria-label="Permalink to &quot;本研一体：按先修能力，而不只按年级选课&quot;">​</a></h2><p>学院建设本硕博一体化课程体系，本科阶段可以在满足先修、选课资格和当学期教学安排的条件下申请修读研究生层次课程。例如，EE291F 在课程表中列为研究生课程，先修为 EE113；EE219 也列出了数字电路、数学与编程基础要求。</p><p><strong>研究生课程向本科生开放，不等于所有课程都无条件可选，也不等于自动获得研究生录取资格。</strong> 学分如何计入本科学位、是否需要教师许可，应向教务和任课教师核实。尤其不要仅凭课程代码判断难度，或为提前修课跳过必要实验训练。</p><h2 id="下一步去哪里" tabindex="-1">下一步去哪里 <a class="header-anchor" href="#下一步去哪里" aria-label="Permalink to &quot;下一步去哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你正在找什么</th><th>推荐入口</th></tr></thead><tbody><tr><td>老师、方向与公开主页</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/faculty">教授与课题组</a></td></tr><tr><td>一份完整的课题组介绍示例</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/vsplab">VSPLab</a></td></tr><tr><td>微纳加工、EDA 与测试资源</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/platforms">科研与工艺平台</a></td></tr><tr><td>实训、联培与特色项目</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/programs">特色培养项目</a></td></tr><tr><td>各方向解决什么问题</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/research/">科研方向</a></td></tr><tr><td>课程先后顺序与课程介绍</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/courses/">课程地图</a></td></tr></tbody></table><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">信息学院官网</a>：首页统计注明「截至 2026 年 09 月」，2026-11 核对。</li><li><a href="https://oaa.shanghaitech.edu.cn/pyfa_4226/list.htm" target="_blank" rel="noreferrer">上海科技大学本科生培养方案</a>：教务处入口，按入学年级和专业选择培养方案，同一栏目提供“课表信息”和“课程信息”入口，2026-11-24 核验。</li><li><a href="https://sist.shanghaitech.edu.cn/2026/0506/c10969a1121576/page.htm" target="_blank" rel="noreferrer">走进信息学院七大研究中心，2026-05-06</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/2711/list.htm" target="_blank" rel="noreferrer">信息学院本科生招生介绍</a>：专业设置、培养特色与本硕博一体化体系。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Undergraduate/Degree%20Programmes/2026%20Bachelor%20Degree%20Prorgams%20in%20EE.htm" target="_blank" rel="noreferrer">2026 级电子信息工程培养方案</a>：学分及三选二规则；本文依据其本地摘录 <code>ee2026_rows.txt</code> 整理。</li><li><a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer">本硕博课程体系与年度开课计划</a>、<a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年开课表</a>：先修与课程层次，以教务系统为准。</li><li>课题组示意使用本站 <code>faculty.ts</code>、<code>directions.ts</code> 的 2026-11 资料版本；具体主页见 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/faculty">教授与课题组</a>。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Undergraduate/Course%20schedule/EE_sample_core_electives.htm" target="_blank" rel="noreferrer">本科生 EE 专业选修课分类图</a>：本科选课指导中包含半导体器件物理、导波光学等高阶课程，并要求关注先修、教学大纲与学分归类；课程层次参照当年开课表。</li></ul>',18))])}const D=r(d,[["render",B]]);export{p as __pageData,D as default};
